CREATE SCHEMA dictionaries;

CREATE TABLE dictionaries.genders (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    genders text NOT NULL
    );
INSERT INTO dictionaries.genders (genders) 
    VALUES ('Male'),('Female'),('Other'),('Anonymous');  

CREATE TABLE dictionaries.roles (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role text NOT NULL,
    description text NOT NULL
    );
INSERT INTO dictionaries.roles (role,description) 
    VALUES ('Superadmin','Ability to directly modify database'),('Admin','Limited ability to modify database'),('Authorizer','Can approve data entries from Enterer role'),('Enterer','Can enter data into the database'),('Student', 'Can enter non-taxonomic data'),('Person','Has no stated privileges');

CREATE TABLE dictionaries.interval_types (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    interval_type text NOT NULL
    );
INSERT INTO dictionaries.interval_types (interval_type) 
    VALUES ('Eon'),('Era'),('Period'),('Epoch'),('Age'),('Zone');

CREATE TABLE dictionaries.zone_types (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    zone_type text NOT NULL
    );
INSERT INTO dictionaries.zone_types (zone_type) 
    VALUES ('trilobite'),('conodont'),('graptolite'),('foraminifera'),('calcareous nannofossil'),('palynomorph'),('mammalia'),('other');

-- from scale_data in original
CREATE TABLE timescales (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    permid integer NOT NULL,
    authorizer_person_id integer REFERENCES people("id"),
    enterer_person_id integer REFERENCES people("id"),
    name text NOT NULL,
    early_age numeric NOT NULL, -- equivalent to b_age/max_age
    late_age numeric NOT NULL, -- equivalent to t_age?min_age
    reference_id integer REFERENCES references("id"),
    preceded_by integer REFERENCES timescales("id"),
    succeeded_by integer REFERENCES timescales("id")
    );

-- From interval_data in original
CREATE TABLE intervals (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    permid integer NOT NULL,
    authorizer_person_id integer REFERENCES people("id"),
    enterer_person_id integer REFERENCES people("id"),
    name text NOT NULL,
    abbreviation varchar(4),
    early_age numeric NOT NULL, -- equivalent to b_age
    late_age numeric NOT NULL, -- equivalent to t_age
    interval_type integer REFERENCES dictionaries.interval_types("id"),
    zone_type integer   REFERENCES dictionaries.zone_types("id"), -- only if interval_type is zone
    reference_id integer REFERENCES references("id"),
    preceded_by integer REFERENCES intervals("id"),
    succeeded_by integer REFERENCES intervals("id")
    );

CREATE TABLE lookup.intervals_timescales (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    interval_id integer REFERENCES intervals("id"),
    timescale_id integer REFERENCES timescales("id")
    );

CREATE TABLE dictionaries.countries (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    abbreviation text NOT NULL,
    full_name text NOT NULL
    );
